  "questions": [
    {
      "n": 1,
      "start": "Weshalb wird die neue, fertiggestellte Kaphaltestelle",
      "end": "immer noch nicht bedient?"
    },
    {
      "n": 2,
      "start": "Wie lange wird an dem für Gehbehinderte und Seniorinnen unnutzbaren Tramhaltestellen-Dauerprovisorium noch festgehalten?",
      "end": "?"
    },
    {
      "n": 3,
      "start": "Bis wann darf die Anwohnerschaft mit einem Abschluss der Arbeiten rechnen?",
      "end": "?"
    },
    {
      "n": 4,
      "start": "Gibt es die seniorenfreundliche Möglichkeit, die Wartebänke der Haltestelle Bettingerstrasse",
      "end": "vorübergehend und unkompliziert an den Standort der provisorischen Haltestelle in der Baselstrasse umzuplatzieren?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Die definitive Haltestelle ist noch nicht fertiggestellt. Es fehlen noch die Deckbeläge.",
      "end": "Die Projektleitung hat bislang auf eine Inbetriebnahme der Haltestelle verzichtet, da spätestens wenn die Deckbelagsarbeiten anstehen wieder eine provisorische Haltestelle genutzt werden muss."
    },
    {
      "n": 2,
      "start": "Der Deckbelag im Bereich der Haltestelle kann mit Beginn der wärmeren Jahreszeit in den kommenden Wochen eingebaut werden.",
      "end": "Somit kann die Haltestelle in Betrieb genommen werden."
    },
    {
      "n": 3,
      "start": "Vom Bauvolumen her sind im Projektperimeter Lörracherstrasse nur noch wenige Arbeiten ausstehend.",
      "end": "Die Arbeiten im Projektperimeter Lörracherstrasse können noch vor den Schulsommerferien abgeschlossen werden."
    },
    {
      "n": 4,
      "start": "Dies ist bereits erfolgt.",
      "end": null
    }
  ],
